import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ebay`,heroTitle:`Optimize your eBay listings in minutes`,heroSubtitle:`Perplexity Computer analyzes your listings, researches competitors, and builds your optimization plan — automatically.`,inputUrlCta:`Optimize my listing`,inputUrlPlaceholder:`e.g. ebay.com/usr/yourstore`,inputUrlPrefill:`Go to {url} and do a full analysis of this eBay store or listing. 1) Audit the title, description, pricing, photos, and item specifics for SEO and conversion best practices. 2) Research the top 10 competing listings for the same or similar products and compare pricing, keywords, and seller ratings. 3) Identify keyword gaps and high-traffic search terms I'm missing. 4) Deliver an optimization plan with rewritten titles, improved descriptions, competitive pricing recommendations, and a 30-day strategy to increase visibility and sales.`,heroOverlaySteps:[`Scanning your eBay listings for title, pricing, and photo quality`,`Researching top 10 competing sellers and their keyword strategies`,`Identifying high-traffic search terms and pricing gaps you're missing`,`Optimized titles, descriptions, and a 30-day growth plan — ready to implement`],generatingSteps:[`Visiting {url} to extract your listings, pricing, and seller details`,`Designing an agent to research competitors and surface keyword opportunities`,`Configuring listing optimization and pricing analysis for your product categories`,`Setting up deliverables for rewritten titles, descriptions, and a growth roadmap`],featureSectionTitle:`From listing to bestseller`,featureCardTitles:[`Connects to your ecommerce stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`eBay, Google Sheets, Google Trends, Notion, Slack — Computer plugs into your tools so listing research, optimization, and tracking happen in one workflow.`,`Optimized listing titles. Rewritten descriptions with keywords. Competitive pricing reports. Photo improvement checklists. A 30-day visibility plan ready for execution.`],capabilitySectionTitle:`Your eBay analyst, on autopilot`,capabilitySectionSubtitle:`Paste your store, step away, come back to a complete optimization strategy.`,capabilityCards:[{title:`Listing Audit`,description:`Computer can analyze every listing in your store — titles, descriptions, item specifics, photos, and pricing — and flag what's hurting your visibility.`},{title:`Competitor Research`,description:`Computer can study top-selling competitors in your category and surface their pricing strategies, keywords, and listing tactics you can adopt.`},{title:`Keyword Optimization`,description:`Computer can identify high-traffic eBay search terms you're missing and rewrite your titles and descriptions to rank higher in search results.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Notion, Slack, and more — build workflows that track inventory, pricing, and listing performance across your stack.`},{title:`Remember & Learn`,description:`Computer can remember your product categories, pricing rules, and brand voice across sessions — so every optimization builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch competitor pricing and listing changes weekly — set up a monitoring workflow that pings you when someone undercuts your top sellers.`}]});export{t as default};
